def is_triangle_free(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(n):
        for j in adj[i]:
            for k in adj[j]:
                if i in adj[k]:
                    return False
    return True

def is_maximal(n, edges):
    # A triangle-free graph is maximal if adding any non-existing edge creates a triangle
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) not in edges and (j, i) not in edges:
                # Check if adding (i, j) creates a triangle
                new_edges = edges + [(i, j)]
                if is_triangle_free(n, new_edges):
                    return False
    return True

